12	// ============================================================
13	// Elementwise 算子 op_host 模板
14	// 适用: ReLU, GELU, Add, Mul 等逐元素算子
15	// 使用: 复制到 csrc/ops/<op_name>/op_host/<op_name>.cpp，
16	//       替换 <op_name>/<OpName>/<dtype> 等占位符
17	// ============================================================
18	
19	#include "torch_kernel_helper.h"
20	#include "tiling/platform/platform_ascendc.h"
21	#include "aclrtlaunch_<op_name>.h"
22	
23	namespace ascend_kernel {
24	
25	constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
26	
27	at::Tensor <op_name>(const at::Tensor &self /* , 其他输入参数 */)
28	{
29	    // ---- 输入校验 ----
30	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat,
31	                "<op_name>: only float16 and float32 are supported, got ", self.scalar_type());
32	
33	    at::Tensor output = at::empty_like(self);
34	
35	    int64_t totalLength = self.numel();
36	    if (totalLength == 0) {
37	        return output;
38	    }
39	
40	    int64_t dtypeSize = self.element_size();
41	
42	    // ---- 获取硬件参数 ----
43	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
44	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
45	    uint64_t ubSize;
46	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
47	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
48	
49	    // ---- Block 级 tiling (核间切分, Cache Line 对齐) ----
50	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
51	    int64_t totalLengthCoreAlign = (totalLengthCore + CACHE_LINE_BYTE_LENGTH - 1)
52	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH;
53	
54	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
55	    int64_t formerNum = usedCoreNum - 1;
56	    int64_t formerLength = totalLengthCoreAlign;
57	    int64_t tailLength = totalLength - formerNum * formerLength;
58	
59	    // ---- UB 级 tiling (核内切分) ----
60	    // bufferCoefficient = 每元素在 UB 中总占用字节, 从设计文档 UB 分配表推导
61	    // 示例: 单输入单输出 + double buffer
62	    //   fp16: 2 queues * 2(double buf) * 2B = 8
63	    //   fp32: 2 queues * 2(double buf) * 4B = 16
64	    int64_t bufferCoefficient = dtypeSize * 4; // <-- 根据实际 UB 分配表修改
65	    if (bufferCoefficient == 0) { bufferCoefficient = 1; }
66	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
67	    if (dtypeSize == 0) { dtypeSize = 1; }
68	    int64_t alignElements = 32 / dtypeSize;
69	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
70	
71	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
72	
73	    EXEC_KERNEL_CMD(<op_name>, blockDim,
74	                    self, output,
75	                    formerNum, formerLength, tailLength, tileLength, dtypeSize);
76	
77	    return output;
78	}
79	
80	}  // namespace ascend_kernel
