{"content": "cmake_minimum_required(VERSION 3.16)
project(foreach_mul_scalar_kernel)

set(CMAKE_CXX_STANDARD 17)

# SOC_VERSION and ASCEND_CANN_PACKAGE_PATH can be passed via -D
if(NOT DEFINED SOC_VERSION)
    set(SOC_VERSION "Ascend910B2")
endif()

if(NOT DEFINED ASCEND_CANN_PACKAGE_PATH)
    set(ASCEND_CANN_PACKAGE_PATH "$ENV{ASCEND_HOME_PATH}")
endif()

set(CANN_INCLUDE ${ASCEND_CANN_PACKAGE_PATH}/include)
set(CANN_COMPILER ${ASCEND_CANN_PACKAGE_PATH}/compiler/ccec_compiler/bin)

# Find PyTorch
execute_process(
    COMMAND python3 -c "import torch; print(torch.__path__[0])"
    OUTPUT_VARIABLE TORCH_PATH
    OUTPUT_STRIP_TRAILING_WHITESPACE
)

include_directories(
    ${TORCH_PATH}/include
    ${TORCH_PATH}/include/torch/csrc/api/include
    ${CANN_INCLUDE}
    ${CMAKE_CURRENT_SOURCE_DIR}
    ${CMAKE_CURRENT_SOURCE_DIR}/utils
)

# AscendC kernel compilation
set(KERNEL_SRC ${CMAKE_CURRENT_SOURCE_DIR}/op_kernel/foreach_mul_scalar.cpp)
set(HOST_SRC ${CMAKE_CURRENT_SOURCE_DIR}/op_host/foreach_mul_scalar.cpp)
set(REGISTER_SRC ${CMAKE_CURRENT_SOURCE_DIR}/register.cpp)

# Use atc to compile AscendC kernel
add_custom_command(
    OUTPUT foreach_mul_scalar.o
    COMMAND ${CANN_COMPILER}/atc
        --single_op=${KERNEL_SRC}
        --soc_version=${SOC_VERSION}
        --output=${CMAKE_CURRENT_BINARY_DIR}/foreach_mul_scalar.o
        --op_name=foreach_mul_scalar
    DEPENDS ${KERNEL_SRC}
)

# Build shared library
add_library(foreach_mul_scalar_ext SHARED
    ${HOST_SRC}
    ${REGISTER_SRC}
)

target_link_libraries(foreach_mul_scalar_ext
    ${TORCH_PATH}/lib/libtorch.so
    ${TORCH_PATH}/lib/libtorch_python.so
    ${TORCH_PATH}/lib/libc10.so
)

set_target_properties(foreach_mul_scalar_ext PROPERTIES
    LIBRARY_OUTPUT_DIRECTORY ${CMAKE_CURRENT_BINARY_DIR}
)
