23	int32_t ChooseBlockM(int32_t mOut)
24	{
25	    for (int32_t candidate : {64, 32, 16, 8, 4, 2}) {
26	        if (candidate <= mOut && mOut % candidate == 0) {
27	            return candidate;
28	        }
29	    }
30	    for (int32_t candidate : {64, 32, 16, 8, 4, 2}) {
31	        if (candidate <= mOut) {
32	            return candidate;
33	        }
34	    }
35	    return 2;
36	}
