38	at::Tensor run_avg_pool3d(const at::Tensor &xFlat,
39	                          int64_t n, int64_t c, int64_t d, int64_t h, int64_t w,
40	                          int64_t od, int64_t oh, int64_t ow,
41	                          int64_t kD, int64_t kH, int64_t kW,
42	                          int64_t sD, int64_t sH, int64_t sW,
43	                          int64_t pD, int64_t pH, int64_t pW,
44	                          int64_t countIncludePad,
45	                          int64_t divisorOverride,
46	                          int64_t ceilMode)
47	{
48	    TORCH_CHECK(xFlat.dim() == 2, "xFlat must be 2D");
49	    TORCH_CHECK(xFlat.is_contiguous(), "xFlat must be contiguous");
50	    TORCH_CHECK(xFlat.scalar_type() == at::kFloat, "AscendC kernel requires float32 input");
51	
52	    const int32_t n32 = static_cast<int32_t>(n);
53	    const int32_t c32 = static_cast<int32_t>(c);
54	    const int32_t d32 = static_cast<int32_t>(d);
55	    const int32_t h32 = static_cast<int32_t>(h);
56	    const int32_t w32 = static_cast<int32_t>(w);
57	
58	    // Channel dimension must be padded to multiple of 8 for 32B DMA alignment
59	    const int32_t paddedC = (static_cast<int32_t>(xFlat.size(1)) + 7) / 8 * 8;
60	    TORCH_CHECK(paddedC == static_cast<int32_t>(xFlat.size(1)),
61	                "xFlat channel dim must be padded to multiple of 8");
62	
63	    const int32_t inSpatial = d32 * h32 * w32;
64	    const int32_t outSpatial = od * oh * ow;
65	    const int32_t mOut = n32 * outSpatial;
66	
67	    TORCH_CHECK(xFlat.size(0) == static_cast<int64_t>(n32) * inSpatial, "xFlat row size mismatch");
68	
69	    const int32_t blockM = ChooseBlockM(mOut);
70	    const int32_t subBlockM = blockM / DEFAULT_VEC_NUM;
71	    const int32_t mNum = mOut / blockM;
72	    const int32_t usedCoreNum = std::min(DEFAULT_NUM_PHYSICAL_CORES, mNum);
73	    const int32_t tasksPerCore = CeilDivI32(mNum, usedCoreNum);
74	
75	    // Output tensor also uses padded channel dimension
76	    at::Tensor yFlat = at::empty({mOut, paddedC}, at::device(at::kPrivateUse1).dtype(at::kFloat));
77	
78	    at::Tensor tilingCpu = at::empty({static_cast<long>(sizeof(AvgPool3DTiling))},
79	                                      at::device(at::kCPU).dtype(at::kByte));
80	    auto *tiling = reinterpret_cast<AvgPool3DTiling *>(tilingCpu.data_ptr());
81	
82	    tiling->N = n32;
83	    tiling->C = c32;
84	    tiling->D = d32;
85	    tiling->H = h32;
86	    tiling->W = w32;
87	
88	    tiling->OD = od;
89	    tiling->OH = oh;
90	    tiling->OW = ow;
91	
92	    tiling->kD = kD;
93	    tiling->kH = kH;
94	    tiling->kW = kW;
95	
96	    tiling->sD = sD;
97	    tiling->sH = sH;
98	    tiling->sW = sW;
99	
100	    tiling->pD = pD;
101	    tiling->pH = pH;
102	    tiling->pW = pW;
103	
104	    tiling->countIncludePad = static_cast<int32_t>(countIncludePad);
105	    tiling->divisorOverride = static_cast<int32_t>(divisorOverride);
106	    tiling->ceilMode = static_cast<int32_t>(ceilMode);
107	
108	    tiling->blockM = blockM;
109	    tiling->subBlockM = subBlockM;
110	    tiling->mNum = mNum;
111	    tiling->outSpatial = outSpatial;
112	    tiling->inSpatial = inSpatial;
113	    tiling->hw = h32 * w32;
114	
115	    tiling->launchBlocks = usedCoreNum;
116	    tiling->vectorLen = std::min<int32_t>(c32, 256);
117	    tiling->paddedC = paddedC;
118	    tiling->reserved1 = 0;
119	
120	    const uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
121	
122	    auto tilingNpu = tilingCpu.to(at::kPrivateUse1);
123	    auto aclStream = c10_npu::getCurrentNPUStream().stream(false);
124	
125	    avg_pool3d_do(blockDim, aclStream,
126	                  static_cast<uint8_t *>(const_cast<void *>(xFlat.storage().data())),
127	                  static_cast<uint8_t *>(const_cast<void *>(yFlat.storage().data())),
128	                  static_cast<uint8_t *>(const_cast<void *>(tilingNpu.storage().data())));
129	
130	    return yFlat;
131	}
