15	template <typename T>
16	class KernelForeachMulScalar {
17	public:
18	    __aicore__ inline KernelForeachMulScalar() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength,
23	                                float scalarValue)
24	    {
25	        int64_t blockIdx = AscendC::GetBlockIdx();
26	
27	        if (blockIdx < formerNum) {
28	            this->blockLength = formerLength;
29	            int64_t offset = formerLength * blockIdx;
30	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
31	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
32	        } else {
33	            this->blockLength = tailLength;
34	            int64_t tailIdx = blockIdx - formerNum;
35	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
36	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
37	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
38	        }
39	
40	        this->tileLength = tileLength;
41	        this->scalarValue = scalarValue;
42	
43	        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
44	        pipe.InitBuffer(outQueueY, BUFFER_NUM, tileLength * sizeof(T));
45	
46	        if constexpr (sizeof(T) == sizeof(half)) {
47	            pipe.InitBuffer(tmpBuf, tileLength * sizeof(float));
48	            pipe.InitBuffer(tmpBufOut, tileLength * sizeof(float));
49	        }
50	    }
51	
52	    __aicore__ inline void Process()
53	    {
54	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
55	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
56	
57	        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
58	        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;
59	
60	        for (int64_t i = 0; i < tileNum - 1; ++i) {
61	            CopyIn(i, this->tileLength);
62	            Compute(i, this->tileLength);
63	            CopyOut(i, this->tileLength);
64	        }
65	        if (tileNum > 0) {
66	            CopyIn(tileNum - 1, alignedTailLen);
67	            Compute(tileNum - 1, alignedTailLen);
68	            CopyOut(tileNum - 1, alignedTailLen);
69	        }
70	    }
71	
72	private:
73	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
74	    {
75	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
76	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
77	        AscendC::DataCopyPad(xLocal, xGm[progress * this->tileLength], copyParams);
78	        inQueueX.EnQue(xLocal);
79	    }
80	
81	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
82	    {
83	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
84	        AscendC::LocalTensor<T> yLocal = outQueueY.AllocTensor<T>();
85	
86	        if constexpr (sizeof(T) == sizeof(float)) {
87	            // float32 / int32: direct compute
88	            AscendC::Muls(yLocal, xLocal, this->scalarValue, curTileLength);
89	        } else {
90	            // fp16 / bf16: Cast up to fp32 -> compute -> Cast down
91	            AscendC::LocalTensor<float> xLocalFp32 = tmpBuf.Get<float>();
92	            AscendC::LocalTensor<float> yLocalFp32 = tmpBufOut.Get<float>();
93	            AscendC::Cast(xLocalFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
94	            AscendC::Muls(yLocalFp32, xLocalFp32, this->scalarValue, curTileLength);
95	            AscendC::Cast(yLocal, yLocalFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
96	        }
97	
98	        outQueueY.EnQue<T>(yLocal);
99	        inQueueX.FreeTensor(xLocal);
100	    }
101	
102	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
103	    {
104	        AscendC::LocalTensor<T> yLocal = outQueueY.DeQue<T>();
105	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
106	        AscendC::DataCopyPad(yGm[progress * this->tileLength], yLocal, copyParams);
107	        outQueueY.FreeTensor(yLocal);
108	    }
109	
110	private:
111	    AscendC::TPipe pipe;
112	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
113	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueY;
114	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
115	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufOut;
116	    AscendC::GlobalTensor<T> xGm;
117	    AscendC::GlobalTensor<T> yGm;
118	    int64_t blockLength;
119	    int64_t tileLength;
120	    float scalarValue;
121	};
122	
123	extern "C" __global__ __aicore__ void foreach_mul_scalar(GM_ADDR x, GM_ADDR y,
124	                                                           int64_t formerNum, int64_t formerLength,
125	                                                           int64_t tailLength, int64_t tileLength,
126	                                                           int64_t dtypeSize, float scalarValue)
127	{
128	    if (dtypeSize == 2) {
129	        KernelForeachMulScalar<half> op;
130	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, scalarValue);
131	        op.Process();
132	    } else if (dtypeSize == 4) {
133	        KernelForeachMulScalar<float> op;
134	        op.Init(x, y, formerNum, formerLength, tailLength, tileLength, scalarValue);
135	        op.Process();
136	    }
137	}
