#include <torch/extension.h>
#include "torch_npu/csrc/core/npu/NPUStream.h"
#include "acl/acl.h"

extern "C" void foreach_mul_scalar_do(
    uint32_t blockDim, void *stream,
    uint8_t *x, uint8_t *y,
    int64_t formerNum, int64_t formerLength,
    int64_t tailLength, int64_t tileLength,
    int64_t dtypeSize, float scalarValue);

namespace foreach_mul_scalar_ext {

at::Tensor run_foreach_mul_scalar(const at::Tensor &x, double scalarValueDouble)
{
    TORCH_CHECK(x.is_contiguous(), "foreach_mul_scalar: input must be contiguous");
    TORCH_CHECK(x.scalar_type() == at::kHalf || x.scalar_type() == at::kFloat ||
                x.scalar_type() == at::kBFloat16 || x.scalar_type() == at::kInt,
                "foreach_mul_scalar: only float16, bfloat16, float32 and int32 are supported");

    at::Tensor y = at::empty_like(x);

    int64_t totalLength = x.numel();
    if (totalLength == 0) {
        return y;
    }

    int64_t dtypeSize = x.element_size();
    float scalarValue = static_cast<float>(scalarValueDouble);

    // Get hardware params
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // Block-level tiling
    constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore * dtypeSize + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH / dtypeSize;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // UB-level tiling
    int64_t bufferCoefficient = (dtypeSize == 2) ? 16 : 20;
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    auto aclStream = c10_npu::getCurrentNPUStream().stream(false);

    foreach_mul_scalar_do(blockDim, aclStream,
                          static_cast<uint8_t *>(const_cast<void *>(x.storage().data())),
                          static_cast<uint8_t *>(const_cast<void *>(y.storage().data())),
                          formerNum, formerLength, tailLength, tileLength,
                          dtypeSize, scalarValue);

    return y;
