24	class RepeatKernel {
25	public:
26	    __aicore__ inline RepeatKernel() {}
27	
28	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tilingGM,
29	                                TPipe *pipe)
30	    {
31	        CopyTiling(&tiling_, tilingGM);
32	
33	        xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), tiling_.inputSize);
34	        yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), tiling_.outputSize);
35	
36	        if ASCEND_IS_AIV {
37	            pipe_ = pipe;
38	            pipe_->InitBuffer(queue_, 1, tiling_.blockM * sizeof(T));
39	        }
40	    }
