42	    __aicore__ inline void Process()
43	    {
44	        if ASCEND_IS_AIV {
45	            for (int localIdx = 0; localIdx < tiling_.tasksPerCore; ++localIdx) {
46	                int bx = coreIdx_ * tiling_.tasksPerCore + localIdx;
47	
48	                for (int r = 0; r < tiling_.subBlockM; ++r) {
49	                    int tileIdx = bx * tiling_.subBlockM + r;
50	
51	                    if (tileIdx >= tiling_.numOutputTiles) {
52	                        continue;
53	                    }
54	
55	                    ProcessTile(tileIdx);
56	                }
57	            }
58	        }
