19	at::Tensor run_foreach_mul_scalar(const at::Tensor &x, double scalarValueDouble)
20	{
21	    TORCH_CHECK(x.is_contiguous(), "foreach_mul_scalar: input must be contiguous");
22	    TORCH_CHECK(x.scalar_type() == at::kHalf || x.scalar_type() == at::kFloat ||
23	                x.scalar_type() == at::kBFloat16 || x.scalar_type() == at::kInt,
24	                "foreach_mul_scalar: only float16, bfloat16, float32 and int32 are supported");
25	
26	    at::Tensor y = at::empty_like(x);
27	
28	    int64_t totalLength = x.numel();
29	    if (totalLength == 0) {
30	        return y;
31	    }
32	
33	    int64_t dtypeSize = x.element_size();
34	    float scalarValue = static_cast<float>(scalarValueDouble);
35	
36	    // Block-level tiling (use default core num)
37	    int64_t coreNum = DEFAULT_CORE_NUM;
38	    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
39	    int64_t totalLengthCoreAlign = (totalLengthCore * dtypeSize + CACHE_LINE_BYTE_LENGTH - 1)
40	                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH / dtypeSize;
41	
42	    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
43	    int64_t formerNum = usedCoreNum - 1;
44	    int64_t formerLength = totalLengthCoreAlign;
45	    int64_t tailLength = totalLength - formerNum * formerLength;
46	
47	    // UB-level tiling (use default UB size)
48	    int64_t bufferCoefficient = (dtypeSize == 2) ? 16 : 20;
49	    int64_t maxTileElements = DEFAULT_UB_SIZE / bufferCoefficient;
50	    int64_t alignElements = 32 / dtypeSize;
51	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
52	    if (tileLength == 0) {
53	        tileLength = alignElements;
54	    }
55	
56	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
57	
58	    auto aclStream = c10_npu::getCurrentNPUStream().stream(false);
59	
60	    foreach_mul_scalar_do(blockDim, aclStream,
61	                          static_cast<uint8_t *>(const_cast<void *>(x.storage().data())),
62	                          static_cast<uint8_t *>(const_cast<void *>(y.storage().data())),
63	                          formerNum, formerLength, tailLength, tileLength,
64	                          dtypeSize, scalarValue);
65	
